body.script:
//
  (async()=>{
    const u=[
      "https://cdn.jsdelivr.net/gh/sealiee11/gnmath@main/practice.html",
      "https://fastly.jsdelivr.net/gh/sealiee11/gnmath@main/practice.html",
      "https://gcore.jsdelivr.net/gh/sealiee11/gnmath@main/practice.html",
      "https://testingcf.jsdelivr.net/gh/sealiee11/gnmath@main/practice.html",
      "https://originfastly.jsdelivr.net/gh/sealiee11/gnmath@main/practice.html",
      "https://quantil.jsdelivr.net/gh/sealiee11/gnmath@main/practice.html",
      "https://jsdelivr.b-cdn.net/gh/sealiee11/gnmath@main/practice.html",
      "https://cdn.statically.io/gh/sealiee11/gnmath@main/practice.html",
      "https://raw.githubusercontent.com/sealiee11/gnmath/main/practice.html",
      "https://github.com/sealiee11/gnmath/raw/main/practice.html",
      "https://raw.githack.com/sealiee11/gnmath/main/practice.html",
      "https://cdn.jsdmirror.com/gh/sealiee11/gnmath@main/practice.html",
      "https://cdn.jsdmirror.cn/gh/sealiee11/gnmath@main/practice.html",
      "https://jsd.onmicrosoft.cn/gh/sealiee11/gnmath@main/practice.html",
      "https://jsd.proxy.aks.moe/gh/sealiee11/gnmath@main/practice.html",
      "https://ghproxy.net/https://raw.github5sercontent.com/sealiee11/gnmath/main/practice.html"
    ];
    const p=document.getElementById("p"), n=document.getElementById("n"), t=document.getElementById("t");
    const est=20971520, stall=20000, minLen=100000, fmt=x=>(x/1048576).toFixed(1)+" MB";

    for(let i=0; i<u.length; i++){
      const ac=new AbortController();
      try{
        t.textContent="Loading..."; n.textContent="Connecting..."; p.style.width="0%";
        const r=await fetch(u[i],{cache:"no-store",signal:ac.signal});
        if(!r.ok||!r.body) continue;
        let total=+(r.headers.get("content-length")||0), enc=r.headers.get("content-encoding"), trusted=!!total&&!enc, rd=r.body.getReader(), a=[], got=0;
        for(;;){
          let tm,q;
          try{
            q=await Promise.race([rd.read(),new Promise((_,rej)=>tm=setTimeout(()=>rej(new Error("stall")),stall))]);
          }finally{clearTimeout(tm)}
          if(q.done) break;
          a.push(q.value); got+=q.value.length;
          if(trusted&&got>total*1.02) trusted=false;
          const den=trusted?total:Math.max(est,got*1.05), pc=Math.min(98,got/den*100);
          p.style.width=pc.toFixed(1)+"%";
          n.textContent=trusted?pc.toFixed(0)+"% · "+fmt(got)+" / "+fmt(total):pc.toFixed(0)+"% · "+fmt(got);
        }
        if(got<minLen) throw new Error("too small");
        const all=new Uint8Array(got); let o=0;
        for(const ch of a){ all.set(ch,o); o+=ch.length; }
        p.style.width="100%"; n.textContent="100% · "+fmt(got);
        const x=new TextDecoder().decode(all);
        if(!x.trim()) continue;
        document.open(); document.write(x); document.close();
        return;
      }catch(e){
        ac.abort(); t.textContent="Trying backup..."; n.textContent="Source "+(i+1)+" failed";
        await new Promise(r=>setTimeout(r,150));
      }
    }
    t.textContent="Failed to load"; n.textContent="All sources failed"; p.style.width="0%";
  })();
//
